      path.setStyle(unchanged ? PARCEL_HOVER_STYLE : { ...editStyle(id), color: PARCEL_HOVER_STYLE.color, weight: PARCEL_HOVER_STYLE.weight })
      path.bringToFront()
    })
    layer.on('mouseout', () => path.setStyle(editStyle(id)))
    layer.on('click', (event) => {
